data.minimal_example:
Chart(
  data: [
  	{'genre': 'Sports', 'sold': 275},
  	{'genre': 'Strategy', 'sold': 115},
  ],
  variables: {
    'genre': Variable(
      accessor: (Map map) => map['genre'] as String,
    ),
    'sold': Variable(
      accessor: (Map map) => map['sold'] as num,
    ),
  },
  marks: [IntervalMark()],
  axes: [
    Defaults.horizontalAxis,
    Defaults.verticalAxis,
  ],
)
